Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
nsfs: tighten permission checks for handle opening

Even privileged services should not necessarily be able to see other
privileged service's namespaces so they can't leak information to each
other. Use may_see_all_namespaces() helper that centralizes this policy
until the nstree adapts.

Link: https://patch.msgid.link/20260226-work-visibility-fixes-v1-2-d2c2853313bd@kernel.org
Fixes: 5222470b2fbb ("nsfs: support file handles")
Reviewed-by: Jeff Layton <jlayton@kernel.org>
Cc: stable@kernel.org # v6.18+
Signed-off-by: Christian Brauner <brauner@kernel.org>

Here is the root cause:
The permission check in `nsfs_fh_to_dentry` used `ns_capable(owning_ns, CAP_SYS_ADMIN)`, which was too permissive. It allowed any process with `CAP_SYS_ADMIN` in the owning namespace to open file handles to that namespace, even if the process belonged to a different privileged service that should not have access. This enabled potential information leakage between privileged services. The fix replaces this with `may_see_all_namespaces()`, a centralized helper that enforces a stricter policy to restrict cross-service visibility.

Here is the patch:

 static struct dentry *nsfs_fh_to_dentry(struct super_block *sb, struct fid *fh,
 					int fh_len, int fh_type)
 {
 	struct path path __free(path_put) = {};
 	struct nsfs_file_handle *fid = (struct nsfs_file_handle *)fh;
 	struct user_namespace *owning_ns = NULL;
 	struct ns_common *ns;
 	int ret;

 	if (fh_len < NSFS_FID_SIZE_U32_VER0)
 		return NULL;

 	/* Check that any trailing bytes are zero. */
 	if ((fh_len > NSFS_FID_SIZE_U32_LATEST) &&
 	    memchr_inv((void *)fid + NSFS_FID_SIZE_U32_LATEST, 0,
 		       fh_len - NSFS_FID_SIZE_U32_LATEST))
 		return NULL;

 	switch (fh_type) {
 	case FILEID_NSFS:
 		break;
 	default:
 		return NULL;
 	}

 	if (!fid->ns_id)
 		return NULL;
 	/* Either both are set or both are unset. */
 	if (!fid->ns_inum != !fid->ns_type)
 		return NULL;

 	scoped_guard(rcu) {
 		ns = ns_tree_lookup_rcu(fid->ns_id, fid->ns_type);
 		if (!ns)
 			return NULL;

 		VFS_WARN_ON_ONCE(ns->ns_id != fid->ns_id);

 		if (fid->ns_inum && (fid->ns_inum != ns->inum))
 			return NULL;
 		if (fid->ns_type && (fid->ns_type != ns->ns_type))
 			return NULL;

 		/*
 		 * This is racy because we're not actually taking an
 		 * active reference. IOW, it could happen that the
 		 * namespace becomes inactive after this check.
 		 * We don't care because nsfs_init_inode() will just
 		 * resurrect the relevant namespace tree for us. If it
 		 * has been active here we just allow it's resurrection.
 		 * We could try to take an active reference here and
 		 * then drop it again. But really, why bother.
 		 */
 		if (!ns_get_unless_inactive(ns))
 			return NULL;
 	}

 	switch (ns->ns_type) {
 #ifdef CONFIG_CGROUPS
 	case CLONE_NEWCGROUP:
 		if (!current_in_namespace(to_cg_ns(ns)))
 			owning_ns = to_cg_ns(ns)->user_ns;
 		break;
 #endif
 #ifdef CONFIG_IPC_NS
 	case CLONE_NEWIPC:
 		if (!current_in_namespace(to_ipc_ns(ns)))
 			owning_ns = to_ipc_ns(ns)->user_ns;
 		break;
 #endif
 	case CLONE_NEWNS:
 		if (!current_in_namespace(to_mnt_ns(ns)))
 			owning_ns = to_mnt_ns(ns)->user_ns;
 		break;
 #ifdef CONFIG_NET_NS
 	case CLONE_NEWNET:
 		if (!current_in_namespace(to_net_ns(ns)))
 			owning_ns = to_net_ns(ns)->user_ns;
 		break;
 #endif
 #ifdef CONFIG_PID_NS
 	case CLONE_NEWPID:
 		if (!current_in_namespace(to_pid_ns(ns))) {
 			owning_ns = to_pid_ns(ns)->user_ns;
 		} else if (!READ_ONCE(to_pid_ns(ns)->child_reaper)) {
 			ns->ops->put(ns);
 			return ERR_PTR(-EPERM);
 		}
 		break;
 #endif
 #ifdef CONFIG_TIME_NS
 	case CLONE_NEWTIME:
 		if (!current_in_namespace(to_time_ns(ns)))
 			owning_ns = to_time_ns(ns)->user_ns;
 		break;
 #endif
 #ifdef CONFIG_USER_NS
 	case CLONE_NEWUSER:
 		if (!current_in_namespace(to_user_ns(ns)))
 			owning_ns = to_user_ns(ns);
 		break;
 #endif
 #ifdef CONFIG_UTS_NS
 	case CLONE_NEWUTS:
 		if (!current_in_namespace(to_uts_ns(ns)))
 			owning_ns = to_uts_ns(ns)->user_ns;
 		break;
 #endif
 	default:
 		return ERR_PTR(-EOPNOTSUPP);
 	}

-	if (owning_ns && !ns_capable(owning_ns, CAP_SYS_ADMIN)) {
+	if (owning_ns && !may_see_all_namespaces()) {
 		ns->ops->put(ns);
 		return ERR_PTR(-EPERM);
 	}

 	/* path_from_stashed() unconditionally consumes the reference. */
 	ret = path_from_stashed(&ns->stashed, nsfs_mnt, ns, &path);
 	if (ret)
 		return ERR_PTR(ret);

 	return no_free_ptr(path.dentry);
 }



